#!/usr/bin/env bash
# Render the generated GitLab job files from their templates.
#
# Usage: generate-gitlab.sh [--check]
#
# Renders, from gitlab/templates/<name>.in:
# - gitlab/jobs/components.yml   component jobs (none yet; later phases add
#                                images, build, unit and sonar jobs);
# - gitlab/jobs/ci-tools-image.yml  the ci-tools image tag, whose hash is the
#                                first 12 hex digits of the sha256 of
#                                ci/docker/ci-tools.DOCKERFILE.
# Each generated file starts with a DO-NOT-EDIT header.
#
# --check  render to a temporary directory and fail (exit 1) if a checked-in
#          file differs from the fresh render. Writes nothing.
# Exit: 0 success, 1 failure or stale files, 2 usage error.
set -euo pipefail

# shellcheck source=ci/lib/common.sh
source "$(dirname "${BASH_SOURCE[0]}")/../lib/common.sh"

usage() {
  sed -n '2,16s/^# \{0,1\}//p' "${BASH_SOURCE[0]}"
}

check=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    --check)
      check=1
      shift
      ;;
    -h | --help)
      usage
      exit 0
      ;;
    *) usage_error "unknown argument '$1' (see --help)" ;;
  esac
done

require_cmd sha256sum sed diff mktemp

TEMPLATE_DIR="${COGNOS_REPO_ROOT}/gitlab/templates"
JOBS_DIR="${COGNOS_REPO_ROOT}/gitlab/jobs"
TOOLS_DOCKERFILE="${COGNOS_CI_DIR}/docker/ci-tools.DOCKERFILE"
GENERATED=(components.yml ci-tools-image.yml)

# image_hash <file>: first 12 hex digits of the sha256 of the file content.
image_hash() {
  local sum
  sum="$(sha256sum "$1")" || die "cannot hash $1"
  printf '%s\n' "${sum:0:12}"
}

# render <name> <out dir>: write <out dir>/<name> from its template.
render() {
  local name="$1" out="$2/$1" template="${TEMPLATE_DIR}/$1.in" hash
  [[ -r "${template}" ]] || die "template not found: ${template}"
  hash="$(image_hash "${TOOLS_DOCKERFILE}")"
  {
    printf '# DO NOT EDIT. Generated by ci/scripts/generate-gitlab.sh from\n'
    printf '# gitlab/templates/%s.in. Regenerate with:\n' "${name}"
    printf '#   bash ci/scripts/generate-gitlab.sh\n'
    printf '#\n'
    sed -e "s/@TOOLS_IMAGE_HASH@/${hash}/g" "${template}"
  } > "${out}"
}

if [[ "${check}" -eq 0 ]]; then
  mkdir -p "${JOBS_DIR}"
  for name in "${GENERATED[@]}"; do
    render "${name}" "${JOBS_DIR}"
    log "wrote gitlab/jobs/${name}"
  done
  exit 0
fi

tmp="$(mktemp -d)"
trap 'rm -rf "${tmp}"' EXIT
stale=0
for name in "${GENERATED[@]}"; do
  render "${name}" "${tmp}"
  if [[ ! -f "${JOBS_DIR}/${name}" ]]; then
    log "missing generated file gitlab/jobs/${name}"
    stale=1
  elif ! diff -u "${JOBS_DIR}/${name}" "${tmp}/${name}" >&2; then
    log "gitlab/jobs/${name} differs from a fresh render (diff above)"
    stale=1
  fi
done
if [[ "${stale}" -ne 0 ]]; then
  die "generated GitLab files are stale; run 'bash ci/scripts/generate-gitlab.sh' and commit the result"
fi
log "generated GitLab files are up to date"
